import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('admin', 'admin@corp.local', 'admin', 'IT')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('jsmith', 'jsmith@corp.local', 'user', 'Finance')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('mjones', 'mjones@corp.local', 'manager', 'HR')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department or role. Supports partial matching."""
    field = request.args.get('field', 'department')
    value = request.args.get('value', '')

    # Restrict searchable fields to prevent schema enumeration
    allowed_fields = ['department', 'role', 'username', 'email']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Value required'}), 400

    # Build query with field validation (field is from allowlist above)
    # Value is user-controlled but we use string formatting for LIKE pattern
    query = f"SELECT id, username, email, role, department FROM users WHERE {field} LIKE '%{value}%' AND active = 1"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID."""
    db = get_db()
    cursor = db.execute('SELECT id, username, email, role, department FROM users WHERE id = ? AND active = 1', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user. Requires JSON body."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'username and email required'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)',
            (data['username'], data['email'], data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
